mapper.update:
UPDATE TB_ITEM
SET
    SORT_ORDER = SORT_ORDER + 1,
    UPDATED_AT = CURRENT_TIMESTAMP
WHERE BOARD_ID = #{boardId}
  AND SORT_ORDER >= #{fromOrder}
  AND SORT_ORDER < #{toOrder}
  AND ITEM_ID != #{excludeItemId}
  AND STATUS NOT IN ('DELETED')

UPDATE TB_ITEM
SET
    SORT_ORDER = SORT_ORDER - 1,
    UPDATED_AT = CURRENT_TIMESTAMP
WHERE BOARD_ID = #{boardId}
  AND SORT_ORDER > #{fromOrder}
  AND SORT_ORDER <= #{toOrder}
  AND ITEM_ID != #{excludeItemId}
  AND STATUS NOT IN ('DELETED')

