SELECT COUNT(*) FROM TB_ITEM i INNER JOIN TB_BOARD b ON i.BOARD_ID = b.BOARD_ID WHERE i.STATUS NOT IN ('COMPLETED', 'DELETED')
AND i.STATUS = #{request.status}
AND i.DUE_DATE IS NOT NULL AND i.DUE_DATE < CURDATE()


WHERE i.TRANSFERRED_FROM IS NOT NULL
  AND i.BOARD_ID = #{boardId}
ORDER BY i.TRANSFERRED_AT DESC

SELECT i.ITEM_ID, i.BOARD_ID, i.OWNER_USERNAME, i.GROUP_ID, i.CATEGORY_ID, i.CONTENT AS TITLE, i.CONTENT, i.DESCRIPTION, i.STATUS, i.PRIORITY, i.ASSIGNEE_USERNAME, i.REQUEST_DATE, i.DUE_DATE, i.PREVIOUS_STATUS, i.COMPLETED_BY, i.DELETED_AT, i.DELETED_BY, i.TRANSFERRED_FROM, i.TRANSFERRED_AT, i.SORT_ORDER, i.CREATED_AT, i.CREATED_BY, i.UPDATED_AT, i.UPDATED_BY, /* v2.2: 하위 업무 필드 */ i.PARENT_ITEM_ID, i.ITEM_DEPTH, i.CHILD_SORT_ORDER, /* v2.2: 하위 업무 계산 필드 */ (SELECT COUNT(*) FROM TB_ITEM child WHERE child.PARENT_ITEM_ID = i.ITEM_ID AND child.STATUS != 'DELETED') AS CHILD_COUNT, (SELECT COUNT(*) FROM TB_ITEM child WHERE child.PARENT_ITEM_ID = i.ITEM_ID AND child.STATUS = 'COMPLETED') AS COMPLETED_CHILD_COUNT, (EXISTS (SELECT 1 FROM TB_ITEM child WHERE child.PARENT_ITEM_ID = i.ITEM_ID AND child.STATUS != 'DELETED')) AS HAS_CHILDREN, (COALESCE(i.ITEM_DEPTH, 0) < 2) AS CAN_CREATE_CHILD, /* v2.2: 부모 업무 정보 */ parent.CONTENT AS PARENT_TITLE, parent.STATUS AS PARENT_STATUS, /* v2.2: 최상위 업무 정보 (CTE 없이 2단계 조인) */ COALESCE(grandparent.ITEM_ID, parent.ITEM_ID) AS ROOT_ITEM_ID, COALESCE(grandparent.CONTENT, parent.CONTENT) AS ROOT_TITLE, COALESCE(grandparent.STATUS, parent.STATUS) AS ROOT_STATUS, b.BOARD_NAME, uo.NAME AS OWNER_NAME, g.GROUP_NAME, g.GROUP_COLOR, cat.CATEGORY_NAME, cat.CATEGORY_COLOR, ua.NAME AS ASSIGNEE_NAME, uc.NAME AS CREATED_BY_NAME, uu.NAME AS UPDATED_BY_NAME, (SELECT COUNT(*) FROM TB_COMMENT c WHERE c.ITEM_ID = i.ITEM_ID) AS COMMENT_COUNT, (SELECT COUNT(*) FROM TB_ITEM_SHARE s WHERE s.ITEM_ID = i.ITEM_ID AND s.DELETED_AT IS NULL) AS SHARE_COUNT, /* 이관 정보 */ tb_orig.OWNER_USERNAME AS TRANSFERRED_BY_USERNAME, ut.NAME AS TRANSFERRED_BY_USER_NAME, /* v2.1: 공유/배정 구분 - SHARE_TYPE에 따라 설정 */ CASE WHEN ish.SHARE_TYPE = 'SHARE' THEN TRUE ELSE FALSE END AS IS_SHARED_TO_ME, CASE WHEN ish.SHARE_TYPE = 'ASSIGN' THEN TRUE ELSE FALSE END AS IS_ASSIGNED_TO_ME, /* 공유 정보 (SHARE_TYPE = 'SHARE'일 때) */ CASE WHEN ish.SHARE_TYPE = 'SHARE' THEN ish.CREATED_BY ELSE NULL END AS SHARED_BY_USERNAME, CASE WHEN ish.SHARE_TYPE = 'SHARE' THEN us.NAME ELSE NULL END AS SHARED_BY_USER_NAME, /* 배정 정보 (SHARE_TYPE = 'ASSIGN'일 때) */ ish.ASSIGNED_BY AS ASSIGNED_BY_USERNAME, /* 서브쿼리로 배정자 이름 조회 (JOIN 문제 우회) */ (SELECT u_ab.NAME FROM TB_USER u_ab WHERE u_ab.USERNAME = ish.ASSIGNED_BY) AS ASSIGNED_BY_USER_NAME, ish.ASSIGNED_AT AS ASSIGNED_AT FROM TB_ITEM i INNER JOIN TB_ITEM_SHARE ish ON i.ITEM_ID = ish.ITEM_ID AND ish.USERNAME = #{username} AND ish.DELETED_AT IS NULL INNER JOIN TB_BOARD b ON i.BOARD_ID = b.BOARD_ID LEFT JOIN TB_USER uo ON i.OWNER_USERNAME = uo.USERNAME LEFT JOIN TB_GROUP g ON i.GROUP_ID = g.GROUP_ID LEFT JOIN TB_CATEGORY cat ON i.CATEGORY_ID = cat.CATEGORY_ID LEFT JOIN TB_USER ua ON i.ASSIGNEE_USERNAME = ua.USERNAME LEFT JOIN TB_USER uc ON i.CREATED_BY = uc.USERNAME LEFT JOIN TB_USER uu ON i.UPDATED_BY = uu.USERNAME LEFT JOIN TB_BOARD tb_orig ON i.TRANSFERRED_FROM = tb_orig.BOARD_ID LEFT JOIN TB_USER ut ON tb_orig.OWNER_USERNAME = ut.USERNAME LEFT JOIN TB_USER us ON ish.CREATED_BY = us.USERNAME /* v2.2: 부모/조부모 업무 조인 */ LEFT JOIN TB_ITEM parent ON i.PARENT_ITEM_ID = parent.ITEM_ID LEFT JOIN TB_ITEM grandparent ON parent.PARENT_ITEM_ID = grandparent.ITEM_ID WHERE i.STATUS NOT IN ('DELETED')
AND i.CONTENT LIKE CONCAT('%', #{request.keyword}, '%')
AND i.STATUS = #{request.status}
AND i.PRIORITY = #{request.priority}
AND i.STATUS != 'COMPLETED'
ORDER BY ish.CREATED_AT DESC
LIMIT #{request.size} OFFSET #{request.offset}

SELECT COUNT(*) FROM TB_ITEM i INNER JOIN TB_ITEM_SHARE ish ON i.ITEM_ID = ish.ITEM_ID AND ish.USERNAME = #{username} AND ish.DELETED_AT IS NULL WHERE i.STATUS NOT IN ('DELETED')
AND i.CONTENT LIKE CONCAT('%', #{request.keyword}, '%')
AND i.STATUS = #{request.status}
AND i.PRIORITY = #{request.priority}
AND i.STATUS != 'COMPLETED'

